package com.hkw.wifi;

import android.Manifest;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.*;
import android.net.wifi.*;
import android.os.*;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.net.*;
import java.util.*;

public class MainActivity extends Activity {
    private static final int REQ_WIFI=41;
    private WifiManager wifi; private LinearLayout content,nav; private TextView status; private ArrayList<ScanResult> results=new ArrayList<>();
    private final int bg=Color.rgb(7,17,29), card=Color.rgb(14,31,48), cyan=Color.rgb(70,217,255), text=Color.rgb(235,245,250), muted=Color.rgb(155,180,195);
    @Override public void onCreate(Bundle b){super.onCreate(b);wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);shell();requestPermissionsIfNeeded();}
    private void shell(){LinearLayout all=new LinearLayout(this);all.setOrientation(LinearLayout.VERTICAL);all.setBackgroundColor(bg);TextView head=label("hkw wi-fi",24,cyan);head.setPadding(20,18,20,8);all.addView(head,new LinearLayout.LayoutParams(-1,62));nav=new LinearLayout(this);nav.setPadding(10,0,10,4);String[] ns={"Home","Analyzer","Speed","Devices"};for(String n:ns){Button b=button(n);nav.addView(b,new LinearLayout.LayoutParams(0,52,1));if(n.equals("Home"))b.setOnClickListener(v->dashboard());if(n.equals("Analyzer"))b.setOnClickListener(v->analyzer());if(n.equals("Speed"))b.setOnClickListener(v->speed());if(n.equals("Devices"))b.setOnClickListener(v->devices());}all.addView(nav);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(18,0,18,18);sc.addView(content);all.addView(sc,new LinearLayout.LayoutParams(-1,0,1));status=label("Ready",13,muted);status.setPadding(20,6,20,8);all.addView(status,new LinearLayout.LayoutParams(-1,38));setContentView(all);dashboard();}
    private TextView label(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(text);b.setTextSize(13);b.setAllCaps(false);return b;}
    private void clear(){content.removeAllViews();}
    private void title(String a,String b){TextView t=label(a,22,text);t.setPadding(0,10,0,2);content.addView(t);TextView x=label(b,13,muted);x.setPadding(0,0,0,10);content.addView(x);}
    private void section(String s){TextView t=label(s,14,cyan);t.setPadding(0,12,0,5);content.addView(t);}
    private TextView cardText(String s){TextView v=label(s,15,text);v.setBackgroundColor(card);v.setPadding(16,13,16,13);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,4,0,4);content.addView(v,p);return v;}
    private void requestPermissionsIfNeeded(){ArrayList<String> p=new ArrayList<>();if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.NEARBY_WIFI_DEVICES)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.NEARBY_WIFI_DEVICES);if(Build.VERSION.SDK_INT<=32&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.ACCESS_FINE_LOCATION);if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),REQ_WIFI);}
    private WifiInfo info(){try{return wifi.getConnectionInfo();}catch(Exception e){return null;}}
    private String ssid(){WifiInfo i=info();return i==null||i.getSSID()==null?"Not connected":i.getSSID().replace("\"","");}
    private String quality(int r){return r>=-55?"Excellent":r>=-67?"Good":r>=-75?"Fair":"Weak";}
    private void dashboard(){clear();title("Network dashboard","Professional Wi-Fi toolkit • local-first");section("CURRENT CONNECTION");WifiInfo i=info();String s="SSID: "+ssid();if(i!=null)s+="\nSignal: "+i.getRssi()+" dBm ("+quality(i.getRssi())+")\nLink speed: "+i.getLinkSpeed()+" Mbps\nFrequency: "+i.getFrequency()+" MHz\nBSSID: "+(i.getBSSID()==null?"Unavailable":i.getBSSID());cardText(s);section("QUICK TOOLS");Button scan=button("Scan nearby networks");Button test=button("Run speed & quality test");Button settings=button("Open Android Wi-Fi settings");content.addView(scan);content.addView(test);content.addView(settings);scan.setOnClickListener(v->analyzer());test.setOnClickListener(v->speed());settings.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS)));section("OFFLINE CAPABILITIES");cardText("Signal, channel analysis, local device scan and saved history work without cloud access. Internet is required only for public speed tests and external DNS/ping targets.");status.setText("Updated "+new Date());}
    private void analyzer(){clear();title("Wi-Fi analyzer","Live access-point list, bands, security and channel quality");Button b=button("Refresh scan");content.addView(b);b.setOnClickListener(v->doScan());doScan();}
    private void doScan(){if(Build.VERSION.SDK_INT<=32&&!((android.location.LocationManager)getSystemService(LOCATION_SERVICE)).isLocationEnabled()){status.setText("Enable Location for Android Wi-Fi scanning");cardText("Android requires Location Services on older versions. Open Settings and enable it, then scan again.");return;}status.setText("Scanning… Android may throttle repeated scans");try{wifi.startScan();new Handler().postDelayed(()->{try{results=new ArrayList<>(wifi.getScanResults());}catch(Exception e){results.clear();}renderScan();},1300);}catch(SecurityException e){cardText("Nearby Wi-Fi permission is required.");}}
    private void renderScan(){clear();title("Wi-Fi analyzer",results.size()+" access points • sorted by signal");Button r=button("Refresh scan");content.addView(r);r.setOnClickListener(v->doScan());if(results.isEmpty()){cardText("No results. Turn Wi-Fi on and grant Nearby devices permission.");return;}Collections.sort(results,(a,z)->z.level-a.level);int best=-1;for(ScanResult x:results)if(best<0||x.level>best)best=x.level;section("CHANNEL OVERVIEW");cardText("Strongest visible signal: "+best+" dBm\nRecommended starting point: choose the least crowded channel in the same band, then confirm with a speed test.");section("ACCESS POINTS");for(ScanResult x:results){String band=x.frequency<3000?"2.4 GHz":x.frequency<6000?"5 GHz":"6 GHz";String name=x.SSID==null||x.SSID.isEmpty()?"Hidden network":x.SSID;Button n=button(name+"\n"+x.level+" dBm • "+quality(x.level)+" • CH "+channel(x.frequency)+" • "+band+"\n"+(x.capabilities==null?"Unknown security":x.capabilities));n.setOnClickListener(v->details(x));content.addView(n);}}
    private void details(ScanResult x){new AlertDialog.Builder(this).setTitle(x.SSID==null?"Hidden network":x.SSID).setMessage("BSSID: "+x.BSSID+"\nFrequency: "+x.frequency+" MHz\nChannel: "+channel(x.frequency)+"\nSignal: "+x.level+" dBm\nSecurity: "+x.capabilities+"\nStandard/channel width: "+x.channelWidth+"\n\nAndroid keeps connection approval with the user.").setPositiveButton("Wi-Fi settings",(d,w)->startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS))).setNegativeButton("Close",null).show();}
    private int channel(int f){if(f>=2412&&f<=2484)return f==2484?14:(f-2407)/5;if(f>=5000)return(f-5000)/5;return 0;}
    private void speed(){clear();title("Speed & quality test","Download/upload use internet data; local checks work offline");TextView out=cardText("Ready. Recommended: run on the Wi-Fi network you want to measure.");Button run=button("Start full test");content.addView(run);Button ping=button("Local gateway + DNS check");content.addView(ping);run.setOnClickListener(v->{run.setEnabled(false);out.setText("Testing ping, download and upload…");new Thread(()->{String result=internetTest();getSharedPreferences("history",0).edit().putString("last",result).apply();runOnUiThread(()->{out.setText(result);run.setEnabled(true);});}).start();});ping.setOnClickListener(v->out.setText(localCheck()));section("MEASUREMENTS");cardText("Ping = response delay. Jitter = variation in delay. Packet loss = failed probes. Download/upload results depend on server, signal, congestion and data allowance.");}
    private String localCheck(){
        ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);
        Network n=cm.getActiveNetwork();
        NetworkCapabilities c=n==null?null:cm.getNetworkCapabilities(n);
        if(c==null)return "SSID: "+ssid()+"\nNetwork unavailable";
        return "SSID: "+ssid()+"\nWi-Fi transport: "+(c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Yes":"No")+"\nValidated internet: "+(c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"Yes":"No");
    }
    private String internetTest(){long p0=System.currentTimeMillis();try{boolean ok=InetAddress.getByName("www.google.com").isReachable(3000);long ping=System.currentTimeMillis()-p0;String dl=downloadTest();String ul=uploadTest();return "Result\nPing: "+ping+" ms • reachable: "+ok+"\nDownload: "+dl+"\nUpload: "+ul+"\nTime: "+new Date();}catch(Exception e){return "Test failed: "+e.getMessage()+"\nCheck internet access and try again.";}}
    private String downloadTest(){long bytes=2_000_000,st=System.currentTimeMillis();try{HttpURLConnection c=(HttpURLConnection)new URL("https://speed.cloudflare.com/__down?bytes="+bytes).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(15000);InputStream in=c.getInputStream();byte[] b=new byte[16384];long got=0;int n;while(got<bytes&&(n=in.read(b))>0)got+=n;in.close();double sec=Math.max(.1,(System.currentTimeMillis()-st)/1000.0);return String.format(Locale.US,"%.2f Mbps",got*8/sec/1_000_000.0);}catch(Exception e){return "Unavailable";}}
    private String uploadTest(){byte[] body=new byte[400_000];new Random().nextBytes(body);long st=System.currentTimeMillis();try{HttpURLConnection c=(HttpURLConnection)new URL("https://speed.cloudflare.com/__up").openConnection();c.setDoOutput(true);c.setRequestMethod("POST");c.setConnectTimeout(5000);c.setReadTimeout(15000);c.getOutputStream().write(body);c.getInputStream().close();double sec=Math.max(.1,(System.currentTimeMillis()-st)/1000.0);return String.format(Locale.US,"%.2f Mbps",body.length*8/sec/1_000_000.0);}catch(Exception e){return "Unavailable";}}
    private void devices(){clear();title("Local network devices","Scan is limited to your current private Wi-Fi subnet");TextView out=cardText("Ready. This checks reachable private IPs only; it does not bypass passwords or scan the public internet.");Button b=button("Start local device scan");content.addView(b);b.setOnClickListener(v->{b.setEnabled(false);out.setText("Scanning local subnet…");new Thread(()->{String r=scanSubnet();runOnUiThread(()->{out.setText(r);b.setEnabled(true);});}).start();});}
    private String scanSubnet(){WifiInfo i=info();if(i==null||i.getIpAddress()==0)return "No active Wi-Fi IP found.";int ip=i.getIpAddress();String base=(ip&255)+"."+((ip>>8)&255)+"."+((ip>>16)&255)+".";int net=(ip>>24)&255;StringBuilder s=new StringBuilder("Reachable devices\n");int count=0;for(int h=1;h<255;h++){if(h==net)continue;try{InetAddress a=InetAddress.getByName(base+h);if(a.isReachable(100)){s.append(base).append(h).append(" • ").append(a.getHostName()).append("\n");count++;}}catch(Exception ignored){}}if(count==0)s.append("No hosts answered; some routers block discovery.");s.append("\nFound: ").append(count);return s.toString();}
}
